function verify(p){assert(p.declarations.length===428,'decl drift '+p.declarations.length);assert(p.dead.length===12,'dead drift '+p.dead.length);const got=p.dead.map(d=>[d.context||'<global>',d.selector,d.property,d.value,d.winnerValue]);assert(JSON.stringify(got)===JSON.stringify(expected),'dead rows drift');}
