async function route(browser){const p=await browser.newPage({viewport:{width:820,height:900}});await p.goto('http://127.0.0.1:4173/.diag-route.html',{waitUntil:'load'});await p.click('[data-order-open="chat"]');await p.waitForTimeout(40);const r=await p.evaluate(()=>({nav:window.__nav,layer:!!document.querySelector('[data-orders-chat-layer]'),api:!!window.DokeOrders?.chat?.openFromCard}));assert(r.api&&r.nav==='mensagens.html?order=ORDER-029'&&!r.layer,'route regression '+JSON.stringify(r));await p.close();console.log('ROUTE REGRESSION PASS|nav=mensagens.html?order=ORDER-029|drawerCreated=0|api=1');}
async function capture(browser,tag){const out={};for(const width of widths){const ctx=await browser.newContext({viewport:{width,height:900}}),p=await ctx.newPage();await p.goto(`http://127.0.0.1:4173/.diag-css.html?${tag}-${width}-${Date.now()}`,{waitUntil:'networkidle'});out[width]=await p.evaluate(()=>{const pick=(s,ps)=>{const e=document.querySelector(s),c=getComputedStyle(e),r=e.getBoundingClientRect(),o={};for(const k of ps)o[k]=c[k];o.rect=[r.x,r.y,r.width,r.height].map(n=>Math.round(n*1000)/1000);return o};return{panel:pick('.orders-chat-panel',['display','width','height','maxHeight','backgroundColor','borderRadius','transform','opacity']),body:pick('.orders-chat-panel__body',['display','gap','paddingTop','paddingRight','paddingBottom','paddingLeft','overflowX','overflowY']),row:pick('.orders-chat-row',['display','maxWidth','width']),rowMe:pick('.orders-chat-row--me',['display','maxWidth','width']),msg:pick('.orders-chat-message',['borderRadius','boxShadow','backgroundColor','backgroundImage']),msgMe:pick('.orders-chat-message--me',['borderRadius','boxShadow','backgroundColor','backgroundImage']),doc:{cw:document.documentElement.clientWidth,sw:document.documentElement.scrollWidth,bcw:document.body.clientWidth,bsw:document.body.scrollWidth}}});assert(out[width].doc.sw<=out[width].doc.cw,'overflow '+width);await ctx.close();}return out;}
function apply(p){const lines=fs.readFileSync(TARGET,'utf8').split(/\r?\n/);for(const d of [...p.dead].sort((a,b)=>b.line-a.line)){assert(lines[d.line-1]?.trim().startsWith(d.property+':'),'line mismatch '+d.line);lines.splice(d.line-1,1);}fs.writeFileSync(TARGET,lines.join('\n'));const n=sh(`git diff --numstat -- ${TARGET}`).split(/\s+/);assert(n[0]==='0'&&n[1]==='12'&&n[2]===TARGET,'delta '+n.join('/'));const a=parse(fs.readFileSync(TARGET,'utf8'));assert(a.declarations.length===416&&a.dead.length===0,`after ${a.declarations.length}/${a.dead.length}`);return crypto.createHash('sha256').update(fs.readFileSync(TARGET)).digest('hex');}
(async()=>{assert(sh('git rev-parse HEAD')===SHA,'wrong sha');assert(sh(`git hash-object ${TARGET}`)===BLOB,'blob drift');const js=fs.readFileSync('assets/js/pages/pedidos/orders-chat.js','utf8');assert((js.match(/\bcreateLayer\s*\(/g)||[]).length===0,'createLayer calls drift');assert(js.includes('return navigateToConversation(order);'),'route source drift');const src=fs.readFileSync(TARGET,'utf8'),beforeBytes=Buffer.byteLength(src),parsed=parse(src);verify(parsed);routeFixture();cssFixture();const server=cp.spawn('python3',['-m','http.server','4173','--bind','127.0.0.1'],{stdio:'ignore'});try{await new Promise(r=>setTimeout(r,650));const browser=await chromium.launch({headless:true});const before=await capture(browser,'before');await route(browser);const hash=apply(parsed),afterBytes=Buffer.byteLength(fs.readFileSync(TARGET));const after=await capture(browser,'after');await browser.close();assert(JSON.stringify(before)===JSON.stringify(after),'runtime parity mismatch');fs.rmSync('.diag-route.html',{force:true});fs.rmSync('.diag-css.html',{force:true});assert(sh('git diff --name-only -- assets index.html resultados.html')===TARGET,'product scope drift');assert(sh('git diff --numstat -- '+TARGET).split(/\s+/).slice(0,2).join('/')==='0/12','final numstat drift');console.log(`CANDIDATE BUILD PASS|hash=${hash}|bytes=${beforeBytes}->${afterBytes}|files=1|additions=0|deletions=12|decl=428->416|dead=12->0`);console.log(`CANDIDATE RUNTIME PASS|viewports=${widths.join(',')}|computed+rect+document/body=0-diffs|overflow=0|boundary=760/761|routeRegression=pass`);fs.writeFileSync('/tmp/ux-css-debt-029-candidate-hash',hash+'\n');}finally{server.kill('SIGTERM');fs.rmSync('.diag-route.html',{force:true});fs.rmSync('.diag-css.html',{force:true});}})().catch(e=>{console.error(e.stack||e);try{cp.execSync(`git reset --hard ${SHA} && git clean -fdx`,{stdio:'inherit'})}catch{}process.exit(1)});